import React from 'react';
import backgroundVid from './background.mp4';
import './Header.css';
export default function Header({CityName, Temperature, HighTemp, LowTemp, Description}){
    return (
        <div class="header">
            <video autoplay loop muted id="backgroundVid" src={backgroundVid} type ="video/webm"/>
            <h1 id="cityname">{CityName}</h1>
            <p id="temp">{Temperature}</p>
            <p id="desc">{Description}</p>
            <p id="maxmin"> H:{HighTemp}  L:{LowTemp}</p>
        </div>
    )

};
